import{u as e}from"./preact-bQZoU-T-.js";import{m as h,w as i}from"./app-gBqMEmJP.js";import{t as o,H as u}from"./auth-Bsjm5qxj.js";import"./legacy-BnM3fQDh.js";import"./firestore-fSAIsBgV.js";import"./firebase-core-XpOECq_A.js";import"./theme-BQmwz7he.js";import"./firebase-auth-CDj-NU_5.js";const n="2026-10-10",a={terms:[{h:"1. რა არის GeoHub",p:["GeoHub არის ქართული სოციალური და აღმოჩენის პლატფორმა: აქ შეგიძლია იპოვო ადგილები და ბიზნესები, გამოაქვეყნო პოსტები, სთორები და ვიდეოები, დაუკავშირდე ადამიანებს და ბიზნესებს, შექმნა ბიზნეს-გვერდი, ჯგუფი ან განცხადება.","პლატფორმით სარგებლობით ეთანხმები ამ პირობებს და კონფიდენციალურობის პოლიტიკას. თუ არ ეთანხმები, ნუ გამოიყენებ GeoHub-ს."]},{h:"2. ანგარიში",p:["ანგარიშის შესაქმნელად უნდა იყო მინიმუმ 16 წლის. 16 წლამდე პირს GeoHub-ის გამოყენება შეუძლია მხოლოდ მშობლის ან კანონიერი წარმომადგენლის თანხმობით.","რეგისტრაციისას მიუთითე ნამდვილი მონაცემები. პასუხისმგებელი ხარ შენი პაროლის დაცვაზე და ყველა მოქმედებაზე, რომელიც შენი ანგარიშიდან ხდება. თუ ფიქრობ, რომ ანგარიშზე სხვამ მოიპოვა წვდომა, შეცვალე პაროლი და მოგვწერე მხარდაჭერის ფორმით.","ერთ ადამიანს შეუძლია ჰქონდეს ერთი პირადი ანგარიში. სხვისი სახელით ან ყალბი ვინაობით ანგარიშის შექმნა აკრძალულია."]},{h:"3. შენი კონტენტი",p:["რასაც აქვეყნებ (ტექსტი, ფოტო, ვიდეო, კომენტარი, შეფასება, შეტყობინება), შენი რჩება. გამოქვეყნებით GeoHub-ს აძლევ არაექსკლუზიურ, უსასყიდლო უფლებას, შეინახოს, აჩვენოს და გაავრცელოს ეს კონტენტი პლატფორმის ფარგლებში, შენ მიერ არჩეული აუდიტორიისთვის (ყველა, მეგობრები, ახლო მეგობრები ან მხოლოდ შენ).","აქვეყნებ მხოლოდ იმას, რისი გაზიარების უფლებაც გაქვს. სხვისი ფოტოს, ნაწარმოების ან პირადი ინფორმაციის გამოქვეყნება მისი ნებართვის გარეშე აკრძალულია.","პოსტის ან ანგარიშის წაშლისას კონტენტი პლატფორმიდან იშლება, თუმცა შეიძლება დროებით დარჩეს სარეზერვო ასლებში ან იქ, სადაც სხვებმა უკვე გააზიარეს."]},{h:"4. რა არის აკრძალული",p:["აკრძალულია: სიძულვილის ენა, მუქარა, შევიწროება და ბულინგი; ძალადობის ან თვითდაზიანების წახალისება; სექსუალური ხასიათის კონტენტი არასრულწლოვნების მონაწილეობით; კანონსაწინააღმდეგო საქონლისა და მომსახურების რეკლამა; თაღლითობა, ყალბი შეფასებები და მოტყუებით ფულის გამოძალვა; სპამი და ავტომატური ანგარიშები; სხვისი პირადი მონაცემების გავრცელება; პლატფორმის უსაფრთხოების გვერდის ავლის ან დაზიანების მცდელობა.","ბიზნეს-გვერდზე მითითებული ინფორმაცია (მისამართი, ფასები, საათები, კონტაქტი) უნდა იყოს ზუსტი. ბიზნესის სახელით გვერდის შექმნა შეუძლია მხოლოდ მის მფლობელს ან უფლებამოსილ პირს."]},{h:"5. საჩივრები და მოდერაცია",p:['წესების დამრღვევ პოსტს, კომენტარს, პროფილს ან ბიზნესს შეგიძლია გაუგზავნო საჩივარი "⋯" მენიუდან. საჩივრებს განიხილავს GeoHub-ის ადმინისტრაცია.',"წესების დარღვევისას შეიძლება წავშალოთ კონტენტი, შევზღუდოთ ფუნქციები ან დავბლოკოთ ანგარიში. თუ ფიქრობ, რომ შეცდომა მოხდა, მოგვწერე მხარდაჭერის ფორმით და გადავხედავთ."]},{h:"6. GeoPoints, ჯილდოები და კუპონები",p:["GeoPoints არის მხოლოდ შიდა ლოიალობის ქულები. ის არ არის ფული, ელექტრონული ფული ან კრიპტოვალუტა, არ ექვემდებარება განაღდებას, გაყიდვას ან სხვა პირზე ფულზე გადაცვლას.","ქულებით მიღებული ჯილდოები და კუპონები მოქმედებს პარტნიორის პირობებით (ვადა, რაოდენობა, გამოყენების წესი). გამოყენებული ქულები ჯილდოს მიღების შემდეგ არ ბრუნდება, გარდა ჩვენი ან პარტნიორის შეცდომისა.","ყალბი აქტივობით, ავტომატიზაციით ან წესების გვერდის ავლით დაგროვილ ქულებს შეიძლება გავაუქმოთ."]},{h:"7. ფასიანი მომსახურება",p:["ზოგიერთი ფუნქცია (მაგალითად, Premium) შეიძლება იყოს ფასიანი. ფასი, პერიოდი და გაუქმების წესი ნაჩვენებია გადახდამდე. გადახდას ამუშავებს საგადახდო პარტნიორი (ბანკი ან საგადახდო სისტემა); ბარათის მონაცემები GeoHub-ში არ ინახება."]},{h:"8. ბიზნესები და მესამე მხარეები",p:["GeoHub აკავშირებს ადამიანებს ბიზნესებთან, მაგრამ არ არის ამ ბიზნესების მომსახურების მხარე. შეკვეთის, ჯავშნისა და მომსახურების ხარისხზე პასუხისმგებელია შესაბამისი ბიზნესი.","პლატფორმაზე შეიძლება იყოს ბმულები სხვა საიტებზე. მათ შინაარსზე და მონაცემების დამუშავებაზე GeoHub არ აგებს პასუხს."]},{h:"9. პასუხისმგებლობა",p:['ვცდილობთ, GeoHub მუშაობდეს შეუფერხებლად და უსაფრთხოდ, თუმცა მომსახურება მოწოდებულია "როგორც არის". არ ვიძლევით გარანტიას, რომ ის იქნება უწყვეტი ან შეცდომების გარეშე.',"კანონით დაშვებულ ფარგლებში GeoHub არ აგებს პასუხს არაპირდაპირ ზიანზე, რომელიც მომხმარებლების ან ბიზნესების მიერ გამოქვეყნებული კონტენტიდან ან მათ შორის ურთიერთობიდან მომდინარეობს."]},{h:"10. ანგარიშის დახურვა",p:['ანგარიშის წაშლა შეგიძლია ნებისმიერ დროს: პარამეტრები → ანგარიში → "ანგარიშის წაშლის მოთხოვნა". მოთხოვნიდან 30 დღის განმავლობაში წავშლით ანგარიშს და მასთან დაკავშირებულ მონაცემებს, გარდა იმისა, რისი შენახვაც კანონით ვალდებულები ვართ.']},{h:"11. ცვლილებები და კანონი",p:["პირობები შეიძლება განახლდეს. არსებითი ცვლილების შესახებ წინასწარ გაცნობებთ პლატფორმაზე. განახლების შემდეგ GeoHub-ის გამოყენება ნიშნავს ახალ პირობებზე თანხმობას.","ამ პირობებზე ვრცელდება საქართველოს კანონმდებლობა. კითხვების შემთხვევაში მოგვწერე მხარდაჭერის ფორმით."]}],privacy:[{h:"1. ვინ ამუშავებს მონაცემებს",p:['GeoHub (შემდგომში "ჩვენ") ამუშავებს შენს პერსონალურ მონაცემებს პლატფორმის მუშაობისთვის, საქართველოს კანონის "პერსონალურ მონაცემთა დაცვის შესახებ" შესაბამისად. ნებისმიერ კითხვაზე მოგვწერე მხარდაჭერის ფორმით (საიტის ქვედა ნაწილში ან პარამეტრებში).']},{h:"2. რა მონაცემებს ვაგროვებთ",p:["ანგარიშის მონაცემები: სახელი, მომხმარებლის სახელი, ელფოსტა, პაროლი (დაშიფრული სახით, მას ვერ ვხედავთ), Google-ით ან Facebook-ით შესვლისას — ამ სერვისის მიერ გადმოცემული სახელი, ელფოსტა და ფოტო.","პროფილის მონაცემები, რასაც თვითონ უთითებ: ფოტო, ქავერი, ბიოგრაფია, ქალაქი, ინტერესები, სამსახური, განათლება. ტელეფონი და დაბადების თარიღი, თუ მიუთითებ, ინახება პირად ნაწილში და სხვებს არ უჩანთ.","კონტენტი და აქტივობა: პოსტები, სთორები, კომენტარები, რეაქციები, შეფასებები, ჩეკინები, შენახული ელემენტები, გამოწერები და მეგობრები, ძიების ბოლო ისტორია (პირად ნაწილში).","შეტყობინებები: პირადი მიმოწერა და ზარების ტექნიკური ჩანაწერები (ვინ, როდის). ზარის ხმა და ვიდეო არ ინახება.",'მდებარეობა: მხოლოდ შენი ნებართვით, მაგალითად რუკაზე "ჩემი მდებარეობისთვის" ან ჩეკინისთვის.',"ტექნიკური მონაცემები: მოწყობილობის და ბრაუზერის ტიპი, შეცდომების ჩანაწერები, შეტყობინებების (push) ტოკენი, თუ შეტყობინებებს ჩართავ."]},{h:"3. რისთვის ვიყენებთ",p:["ანგარიშის შესაქმნელად და დასაცავად; კონტენტის საჩვენებლად შენ მიერ არჩეული აუდიტორიისთვის; მეგობრების, ადგილებისა და ბიზნესების შესათავაზებლად; შეტყობინებების გასაგზავნად; საჩივრების განსახილველად და უსაფრთხოებისთვის; ჯილდოებისა და ფასიანი მომსახურების სამართავად; შეცდომების გამოსასწორებლად და პლატფორმის გასაუმჯობესებლად.","შენს მონაცემებს არ ვყიდით და არ ვიყენებთ მესამე მხარის რეკლამისთვის."]},{h:"4. ვინ ხედავს შენს ინფორმაციას",p:["საჯარო პროფილი (სახელი, ფოტო, ბიოგრაფია, ქალაქი) ყველასთვის ხილულია. პოსტს ხედავს ის აუდიტორია, რომელსაც თავად აირჩევ: ყველა, მეგობრები, ახლო მეგობრები ან მხოლოდ შენ. ეს შეზღუდვა მონაცემთა ბაზის დონეზე მოქმედებს და არა მხოლოდ ეკრანზე.","ელფოსტას, ტელეფონს, დაბადების თარიღსა და ძიების ისტორიას ხედავ მხოლოდ შენ და, აუცილებლობის შემთხვევაში, GeoHub-ის ადმინისტრაცია.","ბიზნესთან მიწერისას შეტყობინებას ხედავს ბიზნეს-გვერდის მფლობელი და ადმინისტრატორები."]},{h:"5. სად ინახება მონაცემები",p:["ვიყენებთ სანდო მომსახურების მიმწოდებლებს: Google Firebase — ანგარიშები, მონაცემთა ბაზა და შეტყობინებები; Cloudinary — ფოტოები და ვიდეოები; Cloudflare — საიტის განთავსება და სერვერული ფუნქციები; საგადახდო პარტნიორი — ფასიანი მომსახურების გადახდა. მათი სერვერები შეიძლება მდებარეობდეს საქართველოს ფარგლებს გარეთ (მაგ., ევროკავშირში ან აშშ-ში); გადაცემა ხდება კანონით გათვალისწინებული დაცვის გარანტიებით."]},{h:"6. რამდენ ხანს ვინახავთ",p:["მონაცემებს ვინახავთ, სანამ ანგარიში აქტიურია. სთორები ავტომატურად ქრება მითითებული ვადის შემდეგ (ჩვეულებრივ 24 საათში). ანგარიშის წაშლის მოთხოვნიდან 30 დღეში ვშლით ანგარიშს და მასთან დაკავშირებულ მონაცემებს; სარეზერვო ასლებიდან ისინი სრულად იშლება დამატებით 30 დღეში. ზოგიერთ ჩანაწერს (მაგ., გადახდის ისტორიას) ვინახავთ იმ ვადით, რასაც კანონი გვავალდებულებს."]},{h:"7. შენი უფლებები",p:["გაქვს უფლება: მოითხოვო ინფორმაცია, რა მონაცემებს ვამუშავებთ; შეასწორო ან განაახლო ისინი (პროფილის რედაქტირებით ან ჩვენთან მოწერით); მოითხოვო წაშლა; შეზღუდო ან გააპროტესტო დამუშავება; გამოიხმო თანხმობა (მაგ., მდებარეობის ან შეტყობინებების). მოთხოვნას ვპასუხობთ კანონით დადგენილ ვადაში.","თუ ფიქრობ, რომ შენი უფლებები დაირღვა, შეგიძლია მიმართო საქართველოს პერსონალურ მონაცემთა დაცვის სამსახურს."]},{h:"8. ბრაუზერის მეხსიერება და ქუქიები",p:["ვიყენებთ ბრაუზერის ლოკალურ მეხსიერებას და Firebase-ის ტექნიკურ ჩანაწერებს შესვლის შესანარჩუნებლად, თემისა და ენის დასამახსოვრებლად და საიტის სწრაფად ჩასატვირთად. სარეკლამო თვალთვალის ქუქიებს არ ვიყენებთ."]},{h:"9. უსაფრთხოება",p:["კავშირი დაშიფრულია (HTTPS), პაროლები ინახება დაშიფრული სახით, ხოლო წვდომა მონაცემებზე იმართება სერვერის დონის წესებით. მიუხედავად ამისა, ინტერნეტში არცერთი სისტემა არ არის აბსოლუტურად დაცული — გამოიყენე ძლიერი პაროლი და არავის გაუზიარო."]},{h:"10. ბავშვები",p:["GeoHub განკუთვნილია 16 წლისა და უფროსი ასაკის პირებისთვის. თუ შეიტყობ, რომ 16 წლამდე ბავშვმა მშობლის თანხმობის გარეშე შექმნა ანგარიში, მოგვწერე და წავშლით."]},{h:"11. ცვლილებები",p:["პოლიტიკის განახლების შემთხვევაში შევცვლით თარიღს ქვემოთ, ხოლო არსებით ცვლილებებზე წინასწარ გაცნობებთ პლატფორმაზე."]}]};function T({doc:p="terms"}){h(o(`legal.${p}`));const r=a[p]||a.terms;return e("div",{class:"page-pad narrow",children:e(i,{class:"legal",children:[e("h1",{class:"page-title",children:o(`legal.${p}`)}),e("p",{class:"muted small",children:o("legal.updated",{date:u(new Date(`${n}T12:00:00`).getTime())})}),r.map(l=>e("section",{class:"legal-section",children:[e("h2",{children:l.h}),l.p.map((s,t)=>e("p",{children:s},t))]},l.h)),e("p",{class:"muted small",children:[o("legal.questions")," ",e("a",{class:"link",href:"/support",children:o("nav.support")})]})]})})}export{T as default};
